uniform float2 u_resolution;
uniform float u_time;
uniform float u_amt;
uniform float4 u_col1;
uniform float4 u_col2;
float random (in float2 _st) {
  return fract(sin(dot(_st.xy, float2(12.9898,78.233)))* 43758.5453123);
}
// Based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise (in float2 _st) {
  float2 i = floor(_st);
  float2 f = fract(_st);
  // Four corners in 2D of a tile
  float a = random(i);
  float b = random(i + float2(1.0, 0.0));
  float c = random(i + float2(0.0, 1.0));
  float d = random(i + float2(1.0, 1.0));
  float2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}
float fbm ( in float2 _st) {
  float v = 0.0;
  float a = 0.5;
  float2 shift = float2(100.0);
  // Rotate to reduce axial bias
  float2x2 rot = float2x2(cos(0.5), sin(0.5),
  -sin(0.5), cos(0.50));
  for (int i = 0; i < 5; ++i) {
    v += a * noise(_st);
    _st = rot * _st * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}
half4 main(float2 p) {
  float2 st = p / 256.;//fragCoord.xy/u_resolution.xy*3.;
  // st += st * abs(sin(u_time*0.1)*3.0);
  float3 color = float3(0.0);
  float2 q = float2(0.);
  q.x = fbm( st + 0.00*u_time);
  q.y = fbm( st + float2(1.0));
  float2 r = float2(0.);
  r.x = fbm( st + 1.0*q + float2(1.7,9.2)+ 0.15*u_time );
  r.y = fbm( st + 1.0*q + float2(8.3,2.8)+ 0.126*u_time);
  float f = fbm(st+r);
  color = mix(float3(0.101961,0.619608,0.666667),
  float3(0.666667,0.666667,0.498039),
  clamp((f*f)*4.0,0.0,1.0));
  color = mix(color,
  float3(0,0,0.164706),
  clamp(length(q),0.0,1.0));
  color = mix(color,
  float3(0.666667,1,1),
  clamp(length(r.x),0.0,1.0));
  return half4((f*f*f+.6*f*f+.5*f)*color,1.);
}

varying float2 vUv;
uniform float2 u_resolution;
uniform float u_time;
uniform float u_amt;

half4 main(float p) {
 	float2 coord = floor(p / 256.);
	float2 res = floor(u_resolution.xy / 4.0);
	float t = time;
	float2 position = (coord / res.xy) - 0.5;
	position.x += sin(time / 4.0) * 0.025 - 0.5;
	position.y += cos(time / 3.0) * 0.025 - 0.5;
	float fog = sqrt(abs(position.x)) / 1.5;
	float ylines = abs(sin((position.y * 16.0 / fog) - t * 8.0));
	float xlines = abs(sin((position.x * 8.0 / fog)));
	float3 color = float3(fog + ylines);
	color -= xlines;
	// give the "walls" a base color
	color += float3(1.75);
	// make it red
	color *= float3(1.0, 0.125, 0.25);
	// fade away into the distance
	color *= fog;

	bool xdither = fract(coord.x / 2.0) != 0.5;
	if(!xdither) {
		color = float3(0.25, 0.0, 0.0) * (fog + 0.5);
	}

	// vingette
	color *= 0.8 - abs((gl_FragCoord.x / u_resolution.x) - 0.5) - abs((gl_FragCoord.y / u_resolution.y) - 0.5);

	return float4(float3(color), 1.0);
}

