varying float2 vUv;
uniform float2 u_resolution;
uniform float u_time;
uniform float u_amt;

half4 main(float p) {
 	float2 coord = floor(p / 256.);
	float2 res = floor(u_resolution.xy / 4.0);
	float t = time;
	float2 position = (coord / res.xy) - 0.5;
	position.x += sin(time / 4.0) * 0.025 - 0.5;
	position.y += cos(time / 3.0) * 0.025 - 0.5;
	float fog = sqrt(abs(position.x)) / 1.5;
	float ylines = abs(sin((position.y * 16.0 / fog) - t * 8.0));
	float xlines = abs(sin((position.x * 8.0 / fog)));
	float3 color = float3(fog + ylines);
	color -= xlines;
	// give the "walls" a base color
	color += float3(1.75);
	// make it red
	color *= float3(1.0, 0.125, 0.25);
	// fade away into the distance
	color *= fog;

	bool xdither = fract(coord.x / 2.0) != 0.5;
	if(!xdither) {
		color = float3(0.25, 0.0, 0.0) * (fog + 0.5);
	}

	// vingette
	color *= 0.8 - abs((gl_FragCoord.x / u_resolution.x) - 0.5) - abs((gl_FragCoord.y / u_resolution.y) - 0.5);

	return float4(float3(color), 1.0);
}

