// BEGINNING OF UNIFORMS
// All are needed to compile the shader, even if not used! The order is fixed!

uniform float2 u_resolution; // the canvas size (width, height)
uniform float u_time; // the editor time in seconds

// audio values (averaged from all bars):
uniform float u_audio_cumulative; // the cumulative audio value, gets added from every update
// (used to be called u_amt)
uniform float u_audio_current; // the current audio value

// the below are not used in the custom shader, but are still needed! They are for the Color 1 and Color 2 options
uniform float4 u_col1;
uniform float4 u_col2;

// END OF UNIFORMS

// Conversion constants
const float M_PI = 3.14159265359;

// Adjustable Parameters
const float GRADIENT_TYPE = 1.0; // Change this to modify the gradient type (1.0: Color Wheel, 2.0: Gradient A, 3.0: Gradient B, 4.0: Gradient C)
const float REPEAT_FREQUENCY = 1.0; // Default value for color wheel density, can be modified
const float ROTATION_SPEED_CONSTANT = 0.25; // Constant rotation speed, based on time
const float ROTATION_SPEED_REACTIVE = 3.0; // Reactive rotation speed, based on cumulative audio
const float TIME_OFFSET = 1.0; // Works great for spectrum layer cascades, try offsetting by 1s!

float3 hsl2rgb(in float3 c) {
    float3 rgb = clamp(abs(mod(c.x * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    return c.z + c.y * (rgb - 0.5) * (1.0 - abs(2.0 * c.z - 1.0));
}

float3 Gradient(float t) {
    if (GRADIENT_TYPE == 1.0) { // Color Wheel (HSL)
        return hsl2rgb(float3(t, 1.0, 0.5));
    } else if (GRADIENT_TYPE == 2.0) { // Gradient A
        float3 c1 = float3(0.514, 0.227, 0.706);
        float3 c2 = float3(0.992, 0.114, 0.114);
        float3 c3 = float3(0.988, 0.69, 0.271);
        t = fract(t) * 3.0;
        return t < 1.0 ? mix(c1, c2, t) : (t < 2.0 ? mix(c2, c3, t - 1.0) : mix(c3, c1, t - 2.0));
    } else if (GRADIENT_TYPE == 3.0) { // Gradient B
        float3 c1 = float3(0.451, 0.012, 0.753);
        float3 c2 = float3(0.925, 0.22, 0.737);
        float3 c3 = float3(0.992, 0.937, 0.976);
        t = fract(t) * 3.0;
        return t < 1.0 ? mix(c1, c2, t) : (t < 2.0 ? mix(c2, c3, t - 1.0) : mix(c3, c1, t - 2.0));
    } else if (GRADIENT_TYPE == 4.0) { // Gradient C
        float3 c1 = float3(1.0, 0.02, 0.486);
        float3 c2 = float3(0.486, 0.392, 0.835);
        float3 c3 = float3(0.298, 0.765, 1.0);
        t = fract(t) * 3.0;
        return t < 1.0 ? mix(c1, c2, t) : (t < 2.0 ? mix(c2, c3, t - 1.0) : mix(c3, c1, t - 2.0));
    }
    return hsl2rgb(float3(t, 1.0, 0.5)); // Default to Color Wheel (HSL)
}

half4 main(float2 p) {
    // Position normalized into (0, 1)
    float2 position = p;
    position.y = 1.0 - position.y; // Flip y to match iOS

    // Position normalized into (-1, 0, 1)
    float2 d = 1.0 - (position * 2.0);

    // Distance from screen center
